import { ValidationMessage } from '@absoluteui/components/validation-message';
import { TextInput } from '@absoluteui/components/text-input';

const inputHost = document.createElement('div');
const messageHost = document.createElement('div');
document.body.append(inputHost, messageHost);
const input = TextInput.create(inputHost, { label: 'Coupon code', name: 'coupon' }).input;
