  if (input.value !== '') message.clear();
});

import { ValidationMessage } from '@absoluteui/components/validation-message';
import { TextInput } from '@absoluteui/components/text-input';

const inputHost = document.createElement('div');
const messageHost = document.createElement('div');
document.body.append(inputHost, messageHost);
const input = TextInput.create(inputHost, { label: 'Handle', name: 'handle' }).input;
const message = ValidationMessage.create(messageHost, { for: input });

async function check(handle: string, signal: AbortSignal): Promise<void> {
  message.setMessage('Checking availability…', 'info');
  const response = await fetch(`/api/handles/${encodeURIComponent(handle)}`, { signal });
  if (response.status === 404) message.setMessage('This handle is available.', 'success');
  else if (response.ok) message.setMessage('This handle is taken.', 'error');
  else message.setMessage('Availability could not be checked.', 'warning');
}

let pending: AbortController | null = null;
input.addEventListener('change', () => {
  pending?.abort();
  const controller = new AbortController();
  pending = controller;
  check(input.value, controller.signal).catch(() => {
    // A newer check aborted this one and owns the message.
    if (!controller.signal.aborted) message.clear();
  });
});

